public final class BookingTableGateway {
  private final DataSource ds;
  public BookingTableGateway(DataSource ds) { this.ds = ds; }

  public List<Slot> slotsFor(String equipment) throws DataAccessException {
    String sql = "select slot_date, minutes, model from slots where equipment = ? order by slot_date";
    try (Connection c = ds.getConnection(); PreparedStatement ps = c.prepareStatement(sql)) {
      ps.setString(1, equipment);
      try (ResultSet rs = ps.executeQuery()) { return mapSlots(rs); }  // rows -> records
    } catch (SQLException e) { throw new DataAccessException("slots(" + equipment + ")", e); }
  }
}
